2777: std::optional<WindowInfo> MainWindow::acquireRenderWindow(bool recreate_window, bool fullscreen, bool render_to_main, bool surfaceless)
2778: {
2779: 	DevCon.WriteLn("acquireRenderWindow() recreate=%s fullscreen=%s render_to_main=%s surfaceless=%s", recreate_window ? "true" : "false",
2780: 		fullscreen ? "true" : "false", render_to_main ? "true" : "false", surfaceless ? "true" : "false");
2781: 
2782: 	const bool is_fullscreen = isRenderingFullscreen();
2783: 	const bool is_rendering_to_main = isRenderingToMain();
2784: 	const bool changing_surfaceless = (!m_display_surface != surfaceless);
2785: 	if (m_display_created && !recreate_window && fullscreen == is_fullscreen && is_rendering_to_main == render_to_main &&
2786: 		!changing_surfaceless)
2787: 	{
2788: 		return m_display_surface ? m_display_surface->getWindowInfo() : WindowInfo();
2789: 	}
2790: 
2791: 	// Skip recreating the surface if we're just transitioning between fullscreen and windowed with render-to-main off.
2792: 	if (m_display_created && !recreate_window && !is_rendering_to_main && !render_to_main && !changing_surfaceless)
2793: 	{
2794: 		DevCon.WriteLn("Toggling to %s without recreating surface", (fullscreen ? "fullscreen" : "windowed"));
2795: 
2796: 		// since we don't destroy the display widget, we need to save it here
2797: 		if (!is_fullscreen && !is_rendering_to_main)
2798: 			saveDisplayWindowGeometryToConfig();
2799: 
2800: #ifdef DISPLAY_SURFACE_WINDOW
2801: 		auto* displayWindow = m_display_surface;
2802: #else
2803: 		auto* displayWindow = m_display_container;
2804: #endif
2805: 		if (fullscreen)
2806: 			displayWindow->showFullScreen();
2807: 		else
2808: 		{
2809: 			// Needs to exit fullscreen before resizing
2810: 			displayWindow->showNormal();
2811: 			if (m_is_temporarily_windowed && g_emu_thread->shouldRenderToMain())
2812: 				displayWindow->setGeometry(geometry());
2813: 			else
2814: 				restoreDisplayWindowGeometryFromConfig();
2815: 		}
2816: 
2817: 		updateDisplayWidgetCursor();
2818: 		m_display_surface->setFocus();
2819: 		updateWindowState();
2820: 
2821: 		QCoreApplication::processEvents(QEventLoop::ExcludeUserInputEvents);
2822: 		return m_display_surface->getWindowInfo();
2823: 	}
2824: 
2825: #ifdef __APPLE__
2826: 	// Skip recreating when toggling fullscreen if we're still rendering to main.
2827: 	if (m_display_created && !recreate_window && is_rendering_to_main && render_to_main && !changing_surfaceless)
2828: 	{
2829: 		updateDisplayRelatedActions(true, true, fullscreen);
2830: 
2831: 		if (fullscreen)
2832: 			showFullScreen();
2833: 		else
2834: 			showNormal();
2835: 
2836: 		while (!m_is_closing && isFullScreen() != fullscreen)
2837: 			QApplication::processEvents(QEventLoop::ExcludeUserInputEvents);
2838: 
2839: 		updateDisplayWidgetCursor();
2840: 		m_display_surface->setFocus();
2841: 		updateWindowState();
2842: 		return m_display_surface->getWindowInfo();
2843: 	}
2844: #endif
2845: 
2846: 	destroyDisplayWidget(surfaceless);
2847: 	m_display_created = true;
2848: 
2849: 	// if we're going to surfaceless, we're done here
2850: 	if (surfaceless)
2851: 		return WindowInfo();
2852: 
2853: 	// very low-chance race here, if the user starts the fullscreen UI, and immediately closes the window.
2854: 	if (m_is_closing)
2855: 	{
2856: 		m_display_created = false;
2857: 		return std::nullopt;
2858: 	}
2859: 
2860: 	createDisplayWidget(fullscreen, render_to_main);
2861: 
2862: 	std::optional<WindowInfo> wi = m_display_surface->getWindowInfo();
2863: 	if (!wi.has_value())
