2866: 		destroyDisplayWidget(true);
2867: 		return std::nullopt;
2868: 	}
2869: 
2870: 	m_display_is_exclusive_fullscreen = g_emu_thread->isExclusiveFullscreen();
2871: 	g_emu_thread->connectDisplaySignals(m_display_surface);
2872: 
2873: 	updateWindowTitle();
2874: 	updateWindowState();
2875: 
2876: 	updateDisplayWidgetCursor();
2877: 	m_display_surface->setFocus();
2878: 	return wi;
